def fa_key(s):
    out = []
    for lvl in ("base", "accent", "variant"):
        ign = _IGN[lvl]
        r = TABLE[lvl]["rank"]
        out.append(tuple(r.get(c, 10 ** 6 + ord(c)) for c in s if c not in ign))
    return tuple(out)


